-- Server-only table (docs/ANALYTICS.md): RLS on and no grants — IPs and other visitors' activity are never readable
-- through the Data API; the collector writes and the admin area reads as the system.
ALTER TABLE public.analytics_events ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
    EXECUTE 'REVOKE ALL ON public.analytics_events FROM anon';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    EXECUTE 'REVOKE ALL ON public.analytics_events FROM authenticated';
  END IF;
END $$;
